// Lets node:test require the actual ui/ TypeScript modules (routes, cron worker, hooks): .ts/.tsx are transpiled with
// the installed TypeScript (read-only), '@/...' maps to ui/src, bare packages resolve from the shared node_modules,
// and '@prisma/client' resolves to the isolated client generated by harness/prisma.cjs.
const fs = require('fs');
const path = require('path');
const Module = require('module');
const { UI_ROOT, NODE_MODULES } = require('./env.cjs');

const ts = require(path.join(NODE_MODULES, 'typescript'));
let prismaClientDir = null;
const mocks = new Map();

const origResolve = Module._resolveFilename;
Module._resolveFilename = function (request, parent, isMain, options) {
  if (mocks.has(request)) return `mock:${request}`;
  if (request === '@prisma/client' && prismaClientDir) return origResolve.call(this, prismaClientDir, parent, isMain, options);
  let req = request;
  if (req.startsWith('@/')) req = path.join(UI_ROOT, 'src', req.slice(2));
  const bare = !req.startsWith('.') && !path.isAbsolute(req) && !req.startsWith('node:') && !Module.builtinModules.includes(req);
  if (bare) {
    try {
      return origResolve.call(this, path.join(NODE_MODULES, req), parent, isMain, options);
    } catch {
      // fall through (a package resolving its own dependency)
    }
  }
  try {
    return origResolve.call(this, req, parent, isMain, options);
  } catch (e) {
    for (const ext of ['.ts', '.tsx', path.sep + 'index.ts', path.sep + 'index.tsx']) {
      try {
        return origResolve.call(this, req + ext, parent, isMain, options);
      } catch {
        // next
      }
    }
    throw e;
  }
};

const origLoad = Module._load;
Module._load = function (request, parent, isMain) {
  if (mocks.has(request)) return mocks.get(request);
  return origLoad.call(this, request, parent, isMain);
};

const compile = (module, filename) => {
  const out = ts.transpileModule(fs.readFileSync(filename, 'utf8'), {
    fileName: filename,
    compilerOptions: {
      module: ts.ModuleKind.CommonJS,
      target: ts.ScriptTarget.ES2020,
      jsx: ts.JsxEmit.ReactJSX,
      esModuleInterop: true,
    },
  });
  module._compile(out.outputText, filename);
};
require.extensions['.ts'] = compile;
require.extensions['.tsx'] = compile;

module.exports = {
  usePrismaClient: dir => {
    prismaClientDir = dir;
  },
  // replaces a module for every later require of exactly this request string
  mock: (request, exports) => mocks.set(request, exports),
  uiPath: (...p) => path.join(UI_ROOT, ...p),
};
